const CLOCK = new Intl.DateTimeFormat(undefined, { hour: 'numeric', minute: '2-digit' });  // module-level, not per row
/** '1:52 PM', or '13:52' when the phone is set to 24-hour time. Same call as ticket/[id].tsx and scan.tsx. */
export function clockTime(iso: string): string { return CLOCK.format(new Date(iso)); }
const startOfDay = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
export function daysAgo(iso: string, now = new Date()): number { return Math.round((startOfDay(now) - startOfDay(new Date(iso))) / 86_400_000); }
/** 'Today', 'Yesterday', 'Monday' (within 6 days), else 'Mon, Sept 7', with ', 2025' only when the year differs. */
export function dayLabel(iso: string): string { const n = daysAgo(iso); const d = new Date(iso); if (n === 0) return 'Today'; if (n === 1) return 'Yesterday'; if (n >= 0 && n < 7) return WEEKDAYS[d.getDay()]; const base = `${WEEKDAYS_SHORT[d.getDay()]}, ${MONTHS[d.getMonth()]} ${d.getDate()}`; return d.getFullYear() === new Date().getFullYear() ? base : `${base}, ${d.getFullYear()}`; }
/** The thread separator: 'Today 1:52 PM'. */
export function separatorLabel(iso: string): string { return `${dayLabel(iso)} ${clockTime(iso)}`; }
/** The list stamp: clock today, 'Yesterday', 'Mon' this week, else 'Sept 7' (', 2025' when not this year). */
export function listTime(iso: string): string { const n = daysAgo(iso); const d = new Date(iso); if (n === 0) return clockTime(iso); if (n === 1) return 'Yesterday'; if (n < 7) return WEEKDAYS_SHORT[d.getDay()]; const md = `${MONTHS[d.getMonth()]} ${d.getDate()}`; return d.getFullYear() === new Date().getFullYear() ? md : `${md}, ${d.getFullYear()}`; }
